const express = require('express');
const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

const app = express();
app.use(express.json());

// Role-based access control
const ROLES = { ADMIN: 'admin', ANALYST: 'analyst', VIEWER: 'viewer' };
const MODEL_REGISTRY = {
  'sentiment-v2': { endpoint: 'http://ml-cluster.internal:8080/predict/sentiment', roles: [ROLES.ADMIN, ROLES.ANALYST] },
  'toxicity-v1': { endpoint: 'http://ml-cluster.internal:8080/predict/toxicity', roles: [ROLES.ADMIN, ROLES.ANALYST] },
  'summary-v3': { endpoint: 'http://ml-cluster.internal:8080/predict/summary', roles: [ROLES.ADMIN] }
};

const ALLOWED_CALLBACK_ORIGINS = ['https://dashboard.company.com', 'https://analytics.company.com'];

function authenticateToken(req, res, next) {
  const token = req.headers['x-api-token'];
  if (!token) return res.status(401).json({ error: 'Missing token' });
  // In production, verify JWT; simplified for demo
  const users = {
    'tok_admin_001': { id: 'u1', role: ROLES.ADMIN },
    'tok_analyst_002': { id: 'u2', role: ROLES.ANALYST },
    'tok_viewer_003': { id: 'u3', role: ROLES.VIEWER }
  };
  const user = users[token];
  if (!user) return res.status(401).json({ error: 'Invalid token' });
  req.user = user;
  next();
}

function authorizeModel(modelId, userRole) {
  const model = MODEL_REGISTRY[modelId];
  if (!model) return { allowed: false, reason: 'Model not found' };
  if (!model.roles.includes(userRole)) return { allowed: false, reason: 'Insufficient permissions' };
  return { allowed: true, endpoint: model.endpoint };
}

// Validates that a URL is safe for internal requests
function isAllowedInternalUrl(urlString) {
  try {
    const parsed = new URL(urlString);
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return false;
    if (parsed.hostname === 'ml-cluster.internal' && parsed.port === '8080') return true;
    return false;
  } catch (e) {
    return false;
  }
}

// Validates callback URLs against allowlist
function isAllowedCallbackUrl(urlString) {
  try {
    const parsed = new URL(urlString);
    const origin = parsed.origin;
    return ALLOWED_CALLBACK_ORIGINS.includes(origin);
  } catch (e) {
    return false;
  }
}

// Normalize model configuration for custom endpoints
function resolveModelEndpoint(modelId, overrideConfig) {
  const baseModel = MODEL_REGISTRY[modelId];
  if (!baseModel) return null;

  if (!overrideConfig || !overrideConfig.endpoint) {
    return baseModel.endpoint;
  }

  // Allow admins to specify custom internal endpoints for A/B testing
  const customEndpoint = overrideConfig.endpoint;
  if (isAllowedInternalUrl(customEndpoint)) {
    return customEndpoint;
  }

  return baseModel.endpoint;
}

// Process inference result and optionally send to callback
async function deliverResult(result, callbackUrl) {
  if (!callbackUrl) return { delivered: false };

  if (!isAllowedCallbackUrl(callbackUrl)) {
    return { delivered: false, reason: 'Callback URL not in allowlist' };
  }

  // POST result to callback
  return new Promise((resolve) => {
    const parsed = new URL(callbackUrl);
    const postData = JSON.stringify(result);
    const options = {
      hostname: parsed.hostname,
      port: parsed.port || 443,
      path: parsed.pathname + parsed.search,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(postData) }
    };
    const req = http.request(options, (res) => resolve({ delivered: true }));
    req.on('error', () => resolve({ delivered: false }));
    req.write(postData);
    req.end();
  });
}

// Main inference endpoint
app.post('/api/v1/infer', authenticateToken, async (req, res) => {
  const { model_id, input, config, callback_url } = req.body;

  if (!model_id || !input) {
    return res.status(400).json({ error: 'model_id and input are required' });
  }

  // Check authorization
  const authResult = authorizeModel(model_id, req.user.role);
  if (!authResult.allowed) {
    return res.status(403).json({ error: authResult.reason });
  }

  // Resolve endpoint (admins can override for A/B testing)
  let targetEndpoint = authResult.endpoint;
  if (req.user.role === ROLES.ADMIN && config) {
    const resolved = resolveModelEndpoint(model_id, config);
    if (resolved) targetEndpoint = resolved;
  }

  // Make inference request
  try {
    const result = await makeInferenceRequest(targetEndpoint, input);

    // Handle async callback delivery
    if (callback_url) {
      await deliverResult(result, callback_url);
    }

    return res.json({ prediction: result, model: model_id });
  } catch (err) {
    return res.status(502).json({ error: 'Inference service unavailable' });
  }
});

// Batch inference with pipeline support
app.post('/api/v1/pipeline', authenticateToken, async (req, res) => {
  const { stages } = req.body;

  if (!Array.isArray(stages) || stages.length === 0) {
    return res.status(400).json({ error: 'Pipeline requires stages array' });
  }

  let pipelineInput = null;
  const results = [];

  for (const stage of stages) {
    const { model_id, input, transform_url } = stage;

    const authResult = authorizeModel(model_id, req.user.role);
    if (!authResult.allowed) {
      return res.status(403).json({ error: `Stage ${model_id}: ${authResult.reason}` });
    }

    const stageInput = pipelineInput || input;
    const result = await makeInferenceRequest(authResult.endpoint, stageInput);

    // Apply intermediate transformation if specified
    if (transform_url) {
      const transformed = await applyTransformation(result, transform_url);
      pipelineInput = transformed;
      results.push(transformed);
    } else {
      pipelineInput = result;
      results.push(result);
    }
  }

  return res.json({ pipeline_results: results });
});

// Apply transformation between pipeline stages
async function applyTransformation(data, transformUrl) {
  // Transform URLs reference internal transformation microservices
  // Format: transform://<service>/<operation>
  const TRANSFORM_SERVICES = {
    'normalize': 'http://transform.internal:9090/normalize',
    'flatten': 'http://transform.internal:9090/flatten',
    'encode': 'http://transform.internal:9090/encode'
  };

  let resolvedUrl;

  if (transformUrl.startsWith('transform://')) {
    const servicePath = transformUrl.slice('transform://'.length);
    const serviceName = servicePath.split('/')[0];
    if (TRANSFORM_SERVICES[serviceName]) {
      resolvedUrl = TRANSFORM_SERVICES[serviceName];
    } else {
      return data; // Unknown service, pass through
    }
  } else {
    // Allow http URLs that pass validation
    resolvedUrl = transformUrl;
  }

  // Validate the resolved URL is internal
  try {
    const parsed = new URL(resolvedUrl);
    const allowedHosts = ['ml-cluster.internal', 'transform.internal'];
    if (!allowedHosts.includes(parsed.hostname)) {
      return data;
    }
  } catch (e) {
    return data;
  }

  return makeInferenceRequest(resolvedUrl, data);
}

async function makeInferenceRequest(endpoint, payload) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(endpoint);
    const postData = JSON.stringify({ input: payload });
    const options = {
      hostname: parsed.hostname,
      port: parsed.port || 80,
      path: parsed.pathname,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(postData) }
    };
    const req = http.request(options, (response) => {
      let body = '';
      response.on('data', (chunk) => body += chunk);
      response.on('end', () => {
        try { resolve(JSON.parse(body)); } catch (e) { resolve({ raw: body }); }
      });
    });
    req.on('error', reject);
    req.setTimeout(5000, () => { req.destroy(); reject(new Error('Timeout')); });
    req.write(postData);
    req.end();
  });
}

